Interface sketch:

// PurgeSource selects eligible rows for deletion in a stable order.
type PurgeSource interface {
  // Select returns a deterministic batch of IDs (or keys) eligible for deletion.
  Select(ctx context.Context, tenantID string, watermark time.Time, cursor Cursor, limit int) (keys []Key, nextCursor Cursor, err error)
}

// PurgeDeleter deletes the selected keys. Must be idempotent.
type PurgeDeleter interface {
  Delete(ctx context.Context, tenantID string, keys []Key) (deleted int, err error)
}

// Checkpoint store persists per-tenant progress.
type PurgeCheckpointStore interface {
  Get(ctx context.Context, tenantID, store string) (Checkpoint, error)
  Set(ctx context.Context, tenantID, store string, cp Checkpoint) error
}

Runner behavior: watermark fixed at run start; checkpoint advances only after successful Delete(); retries do not advance checkpoint.
